import express from 'express'
import { ethers } from 'ethers'
import { SignupProof } from '@unirep/circuits'
import { defaultProver as prover } from '@unirep/circuits/provers/defaultProver'
import ABI from '@unirep-app/contracts/abi/UnirepApp.json'
import { APP_ADDRESS, ETH_PROVIDER_URL, PRIVATE_KEY } from '../config'

const router = express.Router()

router.post('/api/signup', async (req, res) => {
    try {
        const before = new Date()
        const { publicSignals, proof } = req.body

        const signupProof = new SignupProof(publicSignals, proof, prover)
        const valid = await signupProof.verify()
        if (!valid) {
            res.status(400).json({ error: 'Invalid proof' })
            return
        }
        if (APP_ADDRESS === undefined) {
            res.status(400).json({ error: 'APP_ADDRESS is undefined' })
            return
        }
        if (ETH_PROVIDER_URL === undefined) {
            res.status(400).json({ error: 'ETH_PROVIDER_URL is undefined' })
            return
        }
        if (PRIVATE_KEY === undefined) {
            res.status(400).json({ error: 'PRIVATE_KEY is undefined' })
            return
        }
        // make a transaction lil bish
        const provider = new ethers.providers.JsonRpcProvider(ETH_PROVIDER_URL)
        const signer = new ethers.Wallet(PRIVATE_KEY, provider)
        const appContract = new ethers.Contract(APP_ADDRESS, ABI, signer)
        const tx = await appContract.userSignUp(
            signupProof.publicSignals,
            signupProof.proof
        )
        const after = new Date()
        console.log(`Signup took ${after.getTime() - before.getTime()} ms`)
        res.json({ hash: tx.hash })
    } catch (error) {
        res.status(500).json({ error })
    }
})

export default router

import { Router } from 'express'
import { Database } from '../db'
import { config } from '../config'
import { getAgent } from '../services/moltbook'
import {
    createIdentity,
    encryptIdentity,
    createUserState,
} from '../services/unirep'
import { ethers } from 'ethers'

export function signupRouter(db: Database): Router {
    const router = Router()

    router.post('/signup', async (req, res) => {
        try {
            const { moltbookApiKey } = req.body
            if (!moltbookApiKey) {
                return res
                    .status(400)
                    .json({
                        success: false,
                        error: 'moltbookApiKey is required',
                    })
            }

            // Verify agent on Moltbook
            const agent = await getAgent(moltbookApiKey)

            // Check if already registered
            const existing = db.getIdentity(agent.name)
            if (existing) {
                return res
                    .status(409)
                    .json({
                        success: false,
                        error: 'Agent already registered',
                    })
            }

            // Create ZK identity
            const { identity, secret, commitment } = createIdentity()

            // Generate signup proof and submit on-chain
            const userState = await createUserState(identity)
            try {
                const { publicSignals, proof } =
                    await userState.genUserSignUpProof()

                const provider = new ethers.providers.JsonRpcProvider(
                    config.provider
                )
                const wallet = new ethers.Wallet(config.privateKey, provider)
                const karmaBridge = new ethers.Contract(
                    config.karmaBridgeAddress,
                    [
                        'function userSignUp(uint256[] memory publicSignals, uint256[8] memory proof) public',
                    ],
                    wallet
                )
                const tx = await karmaBridge.userSignUp(publicSignals, proof)
                await tx.wait()

                // Store encrypted identity
                const encrypted = encryptIdentity(
                    secret,
                    config.encryptionKey
                )
                db.saveIdentity(agent.name, encrypted, commitment)

                const epoch = await userState.latestTransitionedEpoch()
                res.json({
                    success: true,
                    attesterId: config.karmaBridgeAddress,
                    epoch: Number(epoch),
                })
            } finally {
                userState.stop()
            }
        } catch (err: any) {
            console.error('[signup] Error:', err)
            res.status(500).json({ success: false, error: err.message })
        }
    })

    return router
}

import express from 'express'
import { createDb } from './db'
import { config } from './config'

// Scaffold routes (kept for backwards compatibility)
import appconfig from './routes/appconfig'
import scaffoldSignup from './routes/signup'
import scaffoldRequest from './routes/request'
import transition from './routes/transition'

// Anonbook routes
import { signupRouter } from './routes/anonbook-signup'
import { attestRouter } from './routes/anonbook-attest'
import { postRouter } from './routes/anonbook-post'
import { feedRouter } from './routes/anonbook-feed'

require('dotenv').config()

const app = express()

app.use(express.json())

app.get<{}, any>('/', (req, res) => {
    res.json({
        message: 'Welcome to Anonbook API!',
    })
})
app.use('*', (req, res, next) => {
    res.set('access-control-allow-origin', '*')
    res.set('access-control-allow-headers', '*')
    next()
})

// Scaffold routes
app.use('/', appconfig)
app.use('/', scaffoldSignup)
app.use('/', scaffoldRequest)
app.use('/', transition)

// Anonbook Karma Bridge routes
const db = createDb(config.dbPath)
app.use('/api', signupRouter(db))
app.use('/api', attestRouter(db))
app.use('/api', postRouter(db))
app.use('/api', feedRouter(db))

export default app

import crypto from 'crypto'

const MOLTBOOK_BASE_URL = 'https://www.moltbook.com/api/v1'

export interface MoltbookAgent {
    name: string
    karma: number
    description: string
}

/**
 * Dev mode: when no MOLTBOOK_BOT_API_KEY is set in env, return a stub agent
 * derived from the provided API key string. This lets the full stack
 * work end-to-end without a real Moltbook account.
 */
function devAgent(apiKey: string): MoltbookAgent {
    const hash = crypto
        .createHash('sha256')
        .update(apiKey)
        .digest('hex')
        .slice(0, 8)
    return {
        name: `dev-agent-${hash}`,
        karma: 100,
        description: 'Dev mode stub agent',
    }
}

export async function getAgent(apiKey: string): Promise<MoltbookAgent> {
    // Dev mode: no real Moltbook API key configured
    if (!process.env.MOLTBOOK_BOT_API_KEY) {
        return devAgent(apiKey)
    }

    const res = await fetch(`${MOLTBOOK_BASE_URL}/agents/me`, {
        headers: { Authorization: `Bearer ${apiKey}` },
    })

    if (!res.ok) {
        const body = await res.json().catch(() => ({}))
        throw new Error(body.error || `Moltbook API error: ${res.status}`)
    }

    const { data } = await res.json()
    return {
        name: data.name,
        karma: data.karma ?? 0,
        description: data.description ?? '',
    }
}

import express from 'express'
import { ethers } from 'ethers'
import { EpochKeyProof } from '@unirep/circuits'
import { defaultProver as prover } from '@unirep/circuits/provers/defaultProver'
import ABI from '@unirep-app/contracts/abi/UnirepApp.json'
import { APP_ADDRESS, ETH_PROVIDER_URL, PRIVATE_KEY } from '../config'

const router = express.Router()

router.post('/api/request', async (req, res) => {
    try {
        const before = new Date()
        const { reqData, publicSignals, proof } = req.body

        const epochKeyProof = new EpochKeyProof(publicSignals, proof, prover)
        const valid = await epochKeyProof.verify()
        if (!valid) {
            res.status(400).json({ error: 'Invalid proof' })
            return
        }
        if (APP_ADDRESS === undefined) {
            res.status(400).json({ error: 'APP_ADDRESS is undefined' })
            return
        }
        if (ETH_PROVIDER_URL === undefined) {
            res.status(400).json({ error: 'ETH_PROVIDER_URL is undefined' })
            return
        }
        if (PRIVATE_KEY === undefined) {
            res.status(400).json({ error: 'PRIVATE_KEY is undefined' })
            return
        }
        const provider = new ethers.providers.JsonRpcProvider(ETH_PROVIDER_URL)
        const signer = new ethers.Wallet(PRIVATE_KEY, provider)
        const appContract = new ethers.Contract(APP_ADDRESS, ABI, signer)

        const keys = Object.keys(reqData)
        let tx: any
        if (keys.length === 1) {
            tx = await appContract.submitAttestation(
                epochKeyProof.epochKey,
                epochKeyProof.epoch,
                keys[0],
                reqData[keys[0]]
            )
        } else if (keys.length > 1) {
            tx = await appContract.submitManyAttestations(
                epochKeyProof.epochKey,
                epochKeyProof.epoch,
                keys,
                keys.map((k) => reqData[k])
            )
        }
        const after = new Date()
        console.log(`Request took ${after.getTime() - before.getTime()} ms`)
        res.json({ hash: tx.hash })
    } catch (error: any) {
        res.status(500).json({ error })
    }
})

export default router

